/**
 * @brief 处理示例按钮点击事件并更新按钮文字中的计数值。
 * @param[in] e LVGL 事件对象。
 */
static void btn_event_cb(lv_event_t * e)
{
    lv_event_code_t code = lv_event_get_code(e);
    lv_obj_t * btn = lv_event_get_target(e);
    if(code == LV_EVENT_CLICKED) {
        static uint8_t cnt = 0;
        cnt++;

        /* 获取按钮的第一个子对象标签并更新其文字。 */
        lv_obj_t * label = lv_obj_get_child(btn, 0);
        lv_label_set_text_fmt(label, "Button: %d", cnt);
    }
}

/**
 * @brief 创建一个带文字标签并响应点击事件的 LVGL 示例按钮。
 */
void lv_example_get_started_1(void)
{
    lv_obj_t * btn = lv_btn_create(lv_scr_act());     /* 在当前屏幕创建按钮。 */
    lv_obj_set_pos(btn, 10, 10);                      /* 设置按钮位置。 */
    lv_obj_set_size(btn, 120, 50);                    /* 设置按钮尺寸。 */
    lv_obj_add_event_cb(btn, btn_event_cb, LV_EVENT_ALL, NULL); /* 注册按钮事件回调。 */

    lv_obj_t * label = lv_label_create(btn);          /* 在按钮中创建文字标签。 */
    lv_label_set_text(label, "Button");               /* 设置标签文字。 */
    lv_obj_center(label);
}


