static char * rlottie_sd_json;

/**
 * @brief 在当前屏幕中央显示一条可自动换行的提示信息。
 * @param[in] text 待显示的以空字符结尾的文本。
 */
static void ShowGuiMessage(const char * text)
{
    lv_obj_t * label = lv_label_create(lv_scr_act());
    lv_label_set_text(label, text);
    lv_obj_set_width(label, 150);
    lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);
    lv_obj_center(label);
}

/**
 * @brief 在指定超时时间内等待 SD 卡完成挂载。
 * @param[in] timeout_ms 最长等待时间，单位：毫秒。
 * @retval 0 等待超时后 SD 卡仍未挂载。
 * @retval 1 SD 卡已经挂载。
 */
static uint8_t WaitSdMounted(uint32_t timeout_ms)
{
    uint32_t elapsed_ms = 0;

    while(elapsed_ms < timeout_ms) {
        if(SdManager_IsMounted() != 0U) {
            return 1U;
        }
        osDelay(50);
        elapsed_ms += 50U;
    }

    return (SdManager_IsMounted() != 0U) ? 1U : 0U;
}

/**
 * @brief 从 SD 卡读取 rlottie JSON 文件并追加字符串结束符。
 * @param[in] path FatFs 文件路径。
 * @param[out] json 用于返回 LVGL 内存分配器创建的 JSON 缓冲区。
 * @param[out] json_size 用于返回不含字符串结束符的文件字节数。
 * @return FatFs 操作结果；文件为空、过大、读取不完整或内存不足时返回对应错误。
 * @note 调用者获得缓冲区所有权，失败时函数会自行释放已分配内存。
 */
static FRESULT ReadRlottieJsonFromSd(const char * path, char ** json, uint32_t * json_size)
{
    FIL file;
    FRESULT res;
    FSIZE_t file_size;
    uint32_t file_size32;
    UINT bytes_read = 0;
    char * buffer;

    if(json == NULL || json_size == NULL) {
        return FR_INVALID_PARAMETER;
    }

    *json = NULL;
    *json_size = 0;

    res = f_open(&file, path, FA_READ);
    if(res != FR_OK) {
        return res;
    }

    file_size = f_size(&file);
    if(file_size == 0U || file_size > RLOTTIE_SD_MAX_JSON_SIZE) {
        (void)f_close(&file);
        return FR_INVALID_OBJECT;
    }
    file_size32 = (uint32_t)file_size;

    buffer = lv_mem_alloc((size_t)file_size32 + 1U);
    if(buffer == NULL) {
        (void)f_close(&file);
        return FR_NOT_ENOUGH_CORE;
    }

    res = f_read(&file, buffer, (UINT)file_size32, &bytes_read);
    (void)f_close(&file);

    if(res != FR_OK || bytes_read != (UINT)file_size32) {
        lv_mem_free(buffer);
        return (res != FR_OK) ? res : FR_DISK_ERR;
    }

    buffer[file_size32] = '\0';
    *json = buffer;
    *json_size = file_size32;

    return FR_OK;
}

/**
 * @brief 从 SD 卡加载 JSON 并创建循环播放的 rlottie 动画。
 * @retval 0 SD 卡、文件读取、对象创建或 JSON 解析失败。
 * @retval 1 rlottie 动画创建成功。
 * @note 创建成功后 rlottie_sd_json 必须在动画对象存续期间保持有效。
 */
static uint8_t ShowRlottieSdAnim(void)
{
    FRESULT res;
    uint32_t json_size;
    lv_obj_t * lottie;
    lv_rlottie_t * rlottie;

    if(WaitSdMounted(RLOTTIE_SD_MOUNT_WAIT_MS) == 0U) {
        SEGGER_RTT_WriteString(0, "[GUI] SD not mounted for rlottie\r\n");
        ShowGuiMessage("SD not mounted");
        return 0U;
    }

    res = ReadRlottieJsonFromSd(RLOTTIE_SD_PATH, &rlottie_sd_json, &json_size);
    if(res != FR_OK) {
        SEGGER_RTT_printf(0, "[GUI] read rlottie failed res=%d path=%s\r\n", res, RLOTTIE_SD_PATH);
        ShowGuiMessage("No 0:/rx/anim.jsn");
        return 0U;
    }

    SEGGER_RTT_printf(0, "[GUI] rlottie json loaded %lu bytes from %s\r\n",
                      (unsigned long)json_size,
                      RLOTTIE_SD_PATH);

    lottie = lv_rlottie_create_from_raw(lv_scr_act(),
                                        RLOTTIE_DEMO_SIZE,
                                        RLOTTIE_DEMO_SIZE,
                                        rlottie_sd_json);
    if(lottie == NULL) {
        lv_mem_free(rlottie_sd_json);
        rlottie_sd_json = NULL;
        SEGGER_RTT_WriteString(0, "[GUI] create rlottie object failed\r\n");
        ShowGuiMessage("Lottie create failed");
        return 0U;
    }

    rlottie = (lv_rlottie_t *)lottie;
    if(rlottie->animation == NULL) {
        lv_mem_free(rlottie_sd_json);
        rlottie_sd_json = NULL;
        SEGGER_RTT_WriteString(0, "[GUI] rlottie parse failed\r\n");
        ShowGuiMessage("Lottie parse failed");
        return 0U;
    }

    lv_obj_center(lottie);
    lv_rlottie_set_play_mode(lottie, LV_RLOTTIE_CTRL_PLAY | LV_RLOTTIE_CTRL_LOOP);
    return 1U;
}

/**
 * @brief 使用固件内置 JSON 数据创建循环播放的 rlottie 示例动画。
 */
static void ShowRlottieRawAnim(void)
{
    lv_obj_t * lottie = lv_rlottie_create_from_raw(lv_scr_act(),
                                                   RLOTTIE_DEMO_SIZE,
                                                   RLOTTIE_DEMO_SIZE,
                                                   rlottie_demo_json);
    lv_obj_center(lottie);
    lv_rlottie_set_play_mode(lottie, LV_RLOTTIE_CTRL_PLAY | LV_RLOTTIE_CTRL_LOOP);
}
