/**
 * @brief 将 LVGL 动画输出值应用到 GIF 图像缩放比例。
 * @param[in,out] obj 指向待缩放 LVGL 图像对象的指针。
 * @param[in] zoom LVGL 图像缩放值，256 表示原始尺寸。
 */
static void gif_zoom_anim_cb(void * obj, int32_t zoom)
{
    lv_img_set_zoom((lv_obj_t *)obj, zoom);
}

/**
 * @brief 从 SD 卡创建 GIF，并启动先放大后回放的循环缩放动画。
 * @note 依赖路径 P:/rx/miao.gif 已存在且 LVGL 文件系统端口已初始化。
 */
void ShowGifZoomAnim(void)
{
    lv_obj_t * gif = lv_gif_create(lv_scr_act());
    lv_gif_set_src(gif, "P:/rx/miao.gif");

    /* 120x120 图片中心 */
    lv_img_set_pivot(gif, 60, 60);

    /* 让最终 80x80 居中显示在 160x80 屏幕 */
    lv_obj_set_pos(gif, 20, -20);
    /* 显示尺寸 = 原始尺寸 * zoom / 256 */
    lv_img_set_zoom(gif, 8);

    lv_anim_t a;
    lv_anim_init(&a);
    lv_anim_set_var(&a, gif);
    lv_anim_set_exec_cb(&a, gif_zoom_anim_cb);
    lv_anim_set_values(&a, 8, 270);
    lv_anim_set_time(&a, 1500);
    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);

    lv_anim_set_playback_time(&a, 2000);
    lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
    lv_anim_start(&a);
}


/**
 * @brief 初始化 LCD、LVGL 显示与文件系统端口，并持续刷新摄像头预览界面。
 * @param[in] argument CMSIS-RTOS 任务参数，当前实现不使用该参数。
 * @note 本任务拥有全部 LVGL 对象，其他任务只能通过模块接口提交待显示数据。
 */
void AppGui_Task(void *argument)
{
    (void)argument;
    LCD_Test();
    lv_init();
    lv_port_disp_init();
    lv_port_fs_init();

    AppCamera_GuiInit();

    for (;;) {
        AppCamera_GuiProcess();
        lv_task_handler();
        osDelay(5);
    }
}
